-- SPEC-003: marketing campaigns. utm_campaign is the key the CRM stores on each
-- inquiry, so leads and revenue can be traced to the campaign that brought them.
-- Content and calendar entries may point at the campaign they serve.
-- Append-only: do not edit once applied; add a new migration.

CREATE TABLE content.campaigns (
    workspace_id             uuid NOT NULL,
    id                       bigint GENERATED BY DEFAULT AS IDENTITY (START WITH 1000000),
    legacy_id                bigint,
    name                     text NOT NULL CHECK (length(name) <= 160 AND length(name) >= 1),
    channel                  text NOT NULL CHECK (channel IN ('seo', 'pseo', 'social_organic', 'social_paid', 'email', 'community', 'marketplace', 'outreach', 'referral', 'partner', 'ads_search', 'event', 'other')),
    utm_campaign             text NOT NULL CHECK (utm_campaign ~ '^[a-z0-9][a-z0-9._-]{0,63}$' AND length(utm_campaign) >= 1),
    utm_source               text CHECK (utm_source IS NULL OR (utm_source ~ '^[a-z0-9][a-z0-9._-]{0,63}$')),
    utm_medium               text CHECK (utm_medium IS NULL OR (utm_medium ~ '^[a-z0-9][a-z0-9._-]{0,63}$')),
    status                   text NOT NULL DEFAULT 'planned' CHECK (status IN ('planned', 'active', 'paused', 'ended', 'killed')),
    objective                text CHECK (objective IS NULL OR (length(objective) <= 600)),
    hypothesis               text CHECK (hypothesis IS NULL OR (length(hypothesis) <= 600)),
    offer_ref                text CHECK (offer_ref IS NULL OR (length(offer_ref) <= 120)),
    landing_url              text CHECK (landing_url IS NULL OR (length(landing_url) <= 500)),
    start_date               date,
    end_date                 date,
    budget_thb               integer CHECK (budget_thb IS NULL OR (budget_thb >= 0 AND budget_thb <= 100000000)),
    spend_thb                integer CHECK (spend_thb IS NULL OR (spend_thb >= 0 AND spend_thb <= 100000000)),
    notes                    text,
    version                  bigint NOT NULL DEFAULT 1,
    created_at               timestamptz NOT NULL DEFAULT now(),
    updated_at               timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (workspace_id, id),
    UNIQUE (workspace_id, utm_campaign)
);
CREATE UNIQUE INDEX campaigns_legacy ON content.campaigns (workspace_id, legacy_id) WHERE legacy_id IS NOT NULL;
CREATE INDEX campaigns_channel ON content.campaigns (workspace_id, channel);
CREATE INDEX campaigns_status ON content.campaigns (workspace_id, status);

ALTER TABLE content.content ADD COLUMN campaign_id bigint;
ALTER TABLE content.content ADD CONSTRAINT content_campaign_fk
    FOREIGN KEY (workspace_id, campaign_id) REFERENCES content.campaigns (workspace_id, id);
CREATE INDEX content_campaign_id ON content.content (workspace_id, campaign_id);

ALTER TABLE content.content_calendar ADD COLUMN campaign_id bigint;
ALTER TABLE content.content_calendar ADD CONSTRAINT content_calendar_campaign_fk
    FOREIGN KEY (workspace_id, campaign_id) REFERENCES content.campaigns (workspace_id, id);
CREATE INDEX content_calendar_campaign_id ON content.content_calendar (workspace_id, campaign_id);

ALTER TABLE content.campaigns ENABLE ROW LEVEL SECURITY;
ALTER TABLE content.campaigns FORCE ROW LEVEL SECURITY;
CREATE POLICY workspace_isolation ON content.campaigns
    USING (workspace_id = content.current_workspace())
    WITH CHECK (workspace_id = content.current_workspace());

GRANT SELECT, INSERT, UPDATE, DELETE ON content.campaigns TO content_api;
GRANT USAGE ON SEQUENCE content.campaigns_id_seq TO content_api;
